"""Scoped early Campaign3 claim review, retaining original occurrence identities."""
from pathlib import Path
from fractions import Fraction as F
import json,hashlib,copy
P=Path('docs/planning');B=P/'campaign3-history-universe-rev1';O=P/'campaign3-history-ledger-residual-rev1';O.mkdir(exist_ok=True)
SOURCE='docs/planning/VERDICT_LEDGER.md'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def load(p):return json.loads(Path(p).read_text(encoding='utf-8-sig'))
def save(p,v):
 if p.exists():assert load(p)==v,p
 else:p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n')
specs=[(3036, 'IMPORTANCE', 'Independent same-motive factors separate after urgency change despite equal initial product;7/8 choice sequences differ.', 'Refold equality needs complete history; FrozenProduct failure not every scalar law. Supersedes REV86 bounded gap, no native/execution claim.', ['CAMPAIGN3_IMPORTANCE_URGENCY_QUALIFICATION.md']), (3052, 'UNCERTAINTY', 'Same midpoint/different admitted width changes probability and6/8 sequences; independent audit scores approximate truth.', 'Supersedes REV85/88 uncertainty gaps; truth scoring remains outside cognition. Not calibrated confidence/native execution.', ['CAMPAIGN3_UNCERTAINTY_QUALIFICATION.md']), (3068, 'VIVID', 'Same values/cue/rank distinguish fidelity; false clear recall possible and fragmentation actually removes features.', 'Supersedes REV87 vivid gap; initial identity-basis/unrelated-cue failures retained. Not subjective imagery or native save.', ['CAMPAIGN3_VIVID_RECOLLECTION_QUALIFICATION.md']), (3083, 'AFFECT-RETRIEVAL', 'Actual completed SplitExposure changes later retrieval winner with fixed memory/cue; NoFeedback removes effect.', 'Supersedes retrieval branches of REV87/89, not encoding/salience or scalar necessity; four gains retained.', ['CAMPAIGN3_AFFECT_RETRIEVAL_QUALIFICATION.md']), (3098, 'AFFECT-REDUCTION', 'ScalarUncontrolled equals FullPair across all declared receiver executions including publication/history.', 'Failure of other scalars not vector necessity; regulatory clause remains partial at this date. Prior tests reverified, not rerun.', ['CAMPAIGN3_AFFECT_REDUCTION_COMPARISON.md']), (3113, 'LATENT-CAUSE', 'Motion/resistance evidence discriminates fixed hidden-cause pair; hidden swaps can make inference wrong.', 'Supersedes REV88 diagnosis gap only in equal-prior authored-likelihood scope; no general causal identification.', ['CAMPAIGN3_LATENT_CAUSE_QUALIFICATION.md']), (3130, 'INTERFERENCE', 'Distinct attempts yield cross-episode mean2/3 despite extra same-episode report; source pooling would1/2.', 'Supersedes REV90 recurring-expectation gap; source/native replay separate from component receiver, no joined native claim. Timing/denied-content gaps preserved.', ['CAMPAIGN3_INTERFERENCE_EXPECTATION_QUALIFICATION.md']), (3149, 'CROSS-CONTEXT-COMPONENT', 'Controlled shared meaning changes held-out choices4/8; Refold matches with complete history.', 'Entered meaning/generic execution insufficient actual-domain proof; clause stays partial. Seed7 equality drives all-seed follow-up.', ['CAMPAIGN3_CROSS_CONTEXT_IDENTITY_QUALIFICATION.md']), (3169, 'CROSS-CONTEXT', 'Actual custody/disclosure/attendance enact separate domains under shared actor; local evidence survives global cancellation.', 'Supersedes REV90 cross-context gap boundedly;126 new receiver runs plus18 repeats not144 new. No natural meaning or native integration.', ['CAMPAIGN3_CROSS_CONTEXT_QUALIFICATION.md']), (3189, 'COERCION', 'Actual refusal penalty supplies learned pressure before later choice and eligibility;5/8 actions differ.', 'Supersedes REV90 coercion gap; controlled demander/policy/meaning, not universal coercion or native admission.', ['CAMPAIGN3_ENACTED_COERCION_QUALIFICATION.md']), (3205, 'LONG-GOAL', 'Goal withdrawal/replacement changes8/8 sequences; retained biography affects fine but not coarse response.', 'Supersedes goal branch REV91 only; all24 retention pairs same choices. Preserve coarse failure; no joined native admission.', ['CAMPAIGN3_LONGITUDINAL_GOAL_QUALIFICATION.md']), (3223, 'LONG-ROUTINE', 'Actual resumption/inhibition with maintained/withdrawn/opposed goals; Stored/Derived and retention pairs match.', '504 receiver trajectories not504 native runs;4 joined horizons separate. Old source expiry not forgetting new practice; seed0 delayed resumption preserved.', ['CAMPAIGN3_LONGITUDINAL_ROUTINE_QUALIFICATION.md']), (3245, 'LONG-HABIT', 'Practice-specific episode loss preserves habit; observed renewed practice restores availability8/8, free action4/8.', '960 receiver runs not native admission;4 joined horizons separate. Refold complete history not global erasure; wrong fault oracle/raw scanner retained.', ['CAMPAIGN3_LONGITUDINAL_HABIT_QUALIFICATION.md']), (3267, 'LONG-LOSS', 'Acquired contact relationship, fallible belief, goals and affect feed sampled action after loss.', 'Supersedes loss branch REV91 only; controlled reports/adoption/masked outcomes, not clinical grief/native/vector necessity.', ['CAMPAIGN3_LONGITUDINAL_PERSONAL_LOSS_QUALIFICATION.md']), (3286, 'AFFECT-REGULATORY', 'Same entire body history with different belief gives distinct threat/stress; FullAffect/ScalarThreat preserve64/64.', 'Supersedes body-only regulatory gap, not vector necessity. Four native sentinels not complete native64-run cohort; audit132 bounded not exit.', ['CAMPAIGN3_AFFECT_REGULATORY_QUALIFICATION.md'])]

rows=[]
with (B/'units.jsonl').open(encoding='utf-8') as f:
 for line in f:
  u=json.loads(line)
  if u['source']!=SOURCE or not 3036<=u['location']['startLine']<=3304:continue
  assert u['location']['endLine']<=3304
  _,name,claim,limits,paths=max((s for s in specs if s[0]<=u['location']['startLine']),key=lambda s:s[0])
  rows.append(dict(occurrenceId=u['id'],location=u['location'],text=u['text'],claim=name,disposition=claim,limits=limits,evidence=paths))
raw=(B/'sources'/SOURCE).read_bytes();assert Path(SOURCE).read_bytes().startswith(raw)
lines=raw.decode('utf-8-sig').splitlines(keepends=True)
for r in rows:assert ''.join(lines[r['location']['startLine']-1:r['location']['endLine']])==r['text']
assert {n for r in rows for n in range(r['location']['startLine'],r['location']['endLine']+1)}=={n for n in range(3036,3305) if lines[n-1].strip()}
evidence=[]
for n in sorted({n for s in specs for n in s[4]}):
 p=P/n;evidence.append(dict(path=p.as_posix(),sha256=sha(p)))
v=dict(status='HQ011 RESIDUAL COVERAGE CLAIMS REVIEWED; WIDER AUDIT OPEN',source=dict(path=SOURCE,frozenSha256=sha(B/'sources'/SOURCE)),rows=rows,evidence=evidence,obligations=['RO-C3-001','RO-C3-002','RO-C3-003','RO-C3-004','RO-C3-005','RO-C3-006','RO-C3-007','RO-C3-008','RO-C3-009','RO-C3-010','RO-C3-011','RO-C3-012','RO-C3-013','RO-C3-014','RO-C3-015','RO-C3-016','RO-C3-017','RO-C3-019','RO-C3-020','RO-C3-021','RO-C3-022'],limits=['No fresh production simulation, test suite or build. Receipt bindings do not assert current source freshness for every old receipt.','Fifteen reviewed claim groups retain independent public/component, law and historical correction scopes.'],nextGate='Ledger claim spine reviewed; remaining historical findings/source-role/extraction-boundary reconciliation remains OPEN. Post-cutoff Values delta separately reviewed.')
save(O/'review.json',v)
c=dict(status=v['status'],originalOccurrences=len(rows),claimGroups=len(specs),indexedWholeOccurrenceLinks=875+len(rows),freshBehavioralTests=0,reviewSha256=sha(O/'review.json'),checkerSha256=sha(__file__))
save(O/'check.json',c);print(json.dumps(c))
